**AWS VPC Flow Log Best Practices:**

```hcl
# Terraform: VPC Flow Log Configuration
resource "aws_flow_log" "main" {
  vpc_id          = aws_vpc.main.id
n  traffic_type    = "ALL"         # Log ALL traffic
  log_destination = aws_s3_bucket.flow_logs.arn
  log_destination_type = "s3"

  # Custom format for additional fields
  log_format = "${version} ${account-id} ${interface-id} ${srcaddr} ${dstaddr} ${srcport} ${dstport} ${protocol} ${packets} ${bytes} ${start} ${end} ${action} ${log-status} ${vpc-id} ${subnet-id} ${instance-id} ${tcp-flags}"
}

resource "aws_s3_bucket" "flow_logs" {
  bucket = "vpc-flow-logs-prod"

  versioning { enabled = true }

  lifecycle_rule {
    enabled = true
    transition {
      days          = 90
      storage_class = "GLACIER"
    }
    expiration {
      days = 365
    }
  }
}
```

**Azure NSG Flow Log Best Practices:**

```bicep
// Bicep: NSG Flow Log Configuration
resource nsgFlowLog 'Microsoft.Network/networkWatchers/flowLogs@2023-05-01' = {
  name: 'nsgFlowLog-${nsgName}'
  location: location
  properties: {
    targetResourceId: nsg.id
    storageId: storageAccount.id
    enabled: true
    retentionPolicy: {
      days: 90
      enabled: true
    }
    format: {
      type: 'JSON'
      version: 2  // Version 2 includes flow state
    }
    flowAnalyticsConfiguration: {
      networkWatcherFlowAnalyticsConfiguration: {
        enabled: true
        workspaceResourceId: logAnalyticsWorkspace.id
      }
    }
  }
}
```

**Key Configuration Decisions:**

1. **Traffic Type**: Always log `ALL` (accept + reject). Reject logs catch scanning.
2. **Custom Format**: Include VPC ID, Subnet ID, Instance ID, TCP flags for enrichment.
3. **Retention**: 90 days hot, 365 days cold minimum.
4. **Destination**: S3/Storage Account for long-term, Log Analytics for real-time.
5. **Cost Management**: Use sampling in GCP (0.5-1.0), partition S3 by date.
